class Solution {
  public int[] numMovesStones(int a, int b, int c) {
    int x = Math.min(a, Math.min(b, c)), z = Math.max(a, Math.max(b, c)), y = a + b + c - x - z;
    int max = z - x - 2;
    int min;
    if (z - x == 2) min = 0; // already consecutive
    else if (y - x <= 2 || z - y <= 2) min = 1; // one stone can slot in next to another
    else min = 2;
    return new int[] {min, max};
  }
}
